import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { AuthService } from '../../../core/services/auth.service';
import { ThemeService } from '../../../core/services/theme.service';
import { LangSwitchComponent } from '../../../core/i18n/lang-switch.component';
import { TranslationPipe } from '../../../core/i18n/translation.pipe';
import { ExportService } from '../../../services/export.service';

@Component({
  selector: 'app-navbar',
  standalone: true,
  imports: [CommonModule, RouterModule, LangSwitchComponent, TranslationPipe],
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.scss']
})
export class NavbarComponent implements OnInit {
  isLoggedIn = false;
  isAdmin = false;
  isMobileMenuOpen = false;
  isDarkMode = false;
  userName: string | null = null;
  pageTitle = 'Visão Geral';

  constructor(
    private authService: AuthService,
    private themeService: ThemeService,
    private exportService: ExportService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.checkAuthStatus();
    this.checkThemeMode();
    this.updatePageTitle(this.router.url);

    // Subscrever a mudanças no estado de autenticação
    this.authService.isLoggedIn$.subscribe((loggedIn: boolean) => {
      this.isLoggedIn = loggedIn;
      if (loggedIn) {
        const userData = this.authService.getUserData();
        if (userData) {
          this.userName = userData.nome;
          this.isAdmin = userData.role === 1; // role 1 = admin
        }
      }
    });

    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd)
    ).subscribe((event: NavigationEnd) => {
      this.updatePageTitle(event.urlAfterRedirects);
    });

    // Subscrever a mudanças no tema
    this.themeService.isDarkMode$.subscribe((isDark: boolean) => {
      this.isDarkMode = isDark;
    });
  }

  private checkAuthStatus(): void {
    this.isLoggedIn = this.authService.isAuthenticated();
    if (this.isLoggedIn) {
      const userData = this.authService.getUserData();
      if (userData) {
        this.userName = userData.nome;
        this.isAdmin = userData.role === 1;
      }
    }
  }

  private checkThemeMode(): void {
    this.isDarkMode = this.themeService.isDark();
  }

  toggleTheme(): void {
    this.themeService.toggleTheme();
  }

  toggleMobileMenu(): void {
    this.isMobileMenuOpen = !this.isMobileMenuOpen;
  }

  closeMobileMenu(): void {
    this.isMobileMenuOpen = false;
  }

  logout(): void {
    this.authService.logout();
    this.closeMobileMenu();
    this.router.navigate(['/login']);
  }

  exportCSV(): void {
    const url = this.isAdmin
      ? 'http://localhost/gfp/backend/api/admin/exportar/usuarios'
      : 'http://localhost/gfp/backend/api/exportar/csv';
    const fileName = this.isAdmin ? 'usuarios_sistema.csv' : 'extrato_financeiro.csv';

    this.exportService.exportarCsv(fileName, url).catch((error: Error) => {
      console.error('Erro ao exportar:', error);
    });
  }

  private updatePageTitle(url: string): void {
    if (url.startsWith('/admin')) {
      this.pageTitle = 'Administração';
    } else if (url.startsWith('/transacoes')) {
      this.pageTitle = 'Transações';
    } else if (url.startsWith('/categorias')) {
      this.pageTitle = 'Categorias';
    } else {
      this.pageTitle = 'Visão Geral';
    }
  }
}
 d<aside *ngIf="isLoggedIn" class="sidebar">
  <a [routerLink]="isAdmin ? '/admin' : '/dashboard'" class="brand" (click)="closeMobileMenu()">
    <span class="brand-mark">FS</span>
    <div class="brand-text">
      <strong>FinanSmart</strong>
      <span>Financial Cloud</span>
    </div>
  </a>

  <nav class="side-nav">
    <ng-container *ngIf="!isAdmin; else adminNav">
<span>{{ 'nav.vision_geral' | t }}</span>
<span>{{ 'nav.vision_geral' | t }}</span>
      <a routerLink="/transacoes" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>Transações</span></a>
      <a routerLink="/categorias" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>Categorias</span></a>
    </ng-container>
    <ng-template #adminNav>
      <a routerLink="/admin" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>Administração</span></a>
    </ng-template>
  </nav>

  <div class="sidebar-footer">
    <button class="side-action" (click)="exportCSV()" title="Exportar transações em CSV">Exportar CSV</button>
    <button class="side-action danger" (click)="logout()" title="Sair da conta">Terminar sessão</button>
  </div>
</aside>

<header class="topbar" [class.with-sidebar]="isLoggedIn">
  <div class="topbar-left">
    <h1>{{ pageTitle }}</h1>
    <p *ngIf="isLoggedIn">Olá, <strong>{{ userName }}</strong></p>
  </div>

  <div class="topbar-right">
    <a *ngIf="!isLoggedIn" routerLink="/login" class="auth-link">Entrar</a>
    <a *ngIf="!isLoggedIn" routerLink="/register" class="auth-link primary">Registrar</a>

    <button *ngIf="isLoggedIn" class="mobile-menu-btn" [class.active]="isMobileMenuOpen" (click)="toggleMobileMenu()" aria-label="Abrir menu">
      Menu
    </button>

    <button class="theme-toggle" (click)="toggleTheme()" [title]="isDarkMode ? 'Modo Claro' : 'Modo Escuro'">
      Tema
    </button>

    <app-lang-switch></app-lang-switch>
  </div>
</header>

<div *ngIf="isLoggedIn" class="mobile-drawer" [class.open]="isMobileMenuOpen">
  <ng-container *ngIf="!isAdmin; else adminDrawerNav">
    <a routerLink="/dashboard" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">Visão Geral</a>
    <a routerLink="/transacoes" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">Transações</a>
    <a routerLink="/categorias" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">Categorias</a>
  </ng-container>
  <ng-template #adminDrawerNav>
    <a routerLink="/admin" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">Administração</a>
  </ng-template>
  <button class="drawer-link" (click)="exportCSV(); closeMobileMenu()">Exportar CSV</button>
  <button class="drawer-link danger" (click)="logout()">Terminar sessão</button>
</div>

<nav *ngIf="isLoggedIn" class="bottom-nav">
  <ng-container *ngIf="!isAdmin; else adminBottomNav">
    <a routerLink="/dashboard" routerLinkActive="active" class="bottom-link"><span>Início</span></a>
    <a routerLink="/transacoes" routerLinkActive="active" class="bottom-link"><span>Transações</span></a>
    <a routerLink="/categorias" routerLinkActive="active" class="bottom-link"><span>Categorias</span></a>
  </ng-container>
  <ng-template #adminBottomNav>
    <a routerLink="/admin" routerLinkActive="active" class="bottom-link"><span>Administração</span></a>
  </ng-template>
  <button class="bottom-link" (click)="logout()"><span>Sair</span></button>
</nav>
